var a=`1013-satay-gai`;var t=`world-1013`;var n=`TH`;var r=`southeast-asia`;var s=4;var o=125;var u={en:`Satay Gai`,ua:`Сате з курки`};var g={en:`Satay Gai is a dish from Thailand prepared with chicken thigh, coconut milk, peanut butter, tamarind concentrate. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Сате з курки, страва кухні країни Таїланд, яку готують із таких продуктів: куряче стегно, кокосове молоко, арахісова паста, концентрат тамаринду. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 90 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 90 хвилин.`,t:[`marinating`],m:90,i:[[`chicken-thigh`,700,`g`],[`coconut-milk`,190,`ml`],[`ground-turmeric`,4,`g`],[`ground-coriander`,6,`g`],[`palm-sugar`,18,`g`]]},{en:`Thread the already marinated pieces on skewers, leaving small gaps for even cooking.`,ua:`Нанизайте раніше замариновані шматочки на шпажки з невеликими проміжками для рівного прогрівання.`,t:[`threading-skewers`],m:7,i:[]},{en:`Grill over medium-high heat for about 16 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 16 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:16,i:[[`sunflower-oil`,30,`ml`]]},{en:`Cook the listed sauce ingredients over medium-low heat for about 12 minutes until aromatic and slightly thickened.`,ua:`Готуйте складники соусу на помірно слабкому вогні приблизно 12 хвилин до появи аромату та легкого загустіння.`,t:[`sauteing`,`reducing-sauce`],m:12,i:[[`peanut-butter`,150,`g`],[`coconut-milk`,150,`ml`],[`tamarind-concentrate`,25,`g`],[`fish-sauce`,15,`ml`],[`palm-sugar`,25,`g`]]}];var d={slug:a,id:t,country:`TH`,region:r,servings:4,minutes:125,title:u,text:g,steps:l};export{n as country,d as default,t as id,o as minutes,r as region,s as servings,a as slug,l as steps,g as text,u as title};